#include <bits/stdc++.h>using namespace std;using ll = int32_t; int main() {	// your code goes here	int T ;	cin >> T;		while(T --){	    int n ; 	    cin >> n ;	    	    vector<int>vec(n);	    ll two = 0;	   	    for(auto &x : vec){	        cin >> x;	        	        if(x == 2){	            two ++;	        }	    }	    	    	    if(two == 0){	        cout << 1 << endl;	        continue;	    }	    	    if(two & 1){	        cout << -1 << endl ;	        continue ;	    }	    	    else{	        int half = two / 2;	        	        for(int i = 0 ; i < n ; i ++){	            if(vec[i] == 2){	                half --;	                	                if(half == 0){	                    cout << i + 1 << endl ; 	                    continue ;	                }	            }	        }	    }  	} }